function showSoloSeatControls(){
 if(!soloTestMode||typeof MTGSoloTest==='undefined')return toast('Solo Test is not active.');
 const seats=MTGSoloTest.virtualSeats(players);if(!seats.length)return toast('No virtual seats available.');
 const paused=!!st?.soloNPC?.paused,autoLabel=paused?'NPC AUTO PLAY · RESUME':'NPC AUTO PLAY · PAUSE';
 choice([autoLabel,...seats.map(p=>'P'+p.id+' · '+p.name+' · '+(p.deckName||'NPC Deck'))],pick=>{
   if(pick===autoLabel){let now=MTGSoloNPC.togglePause(st);clearTimeout(soloNpcTimer);soloNpcTimer=null;sync();if(!now)scheduleSoloNpc(300);toast('NPC auto play '+(now?'paused.':'resumed.'));return}
   let m=pick.match(/^P(\d+)/),id=Number(m&&m[1]);if(!id)return;
   choice(['Life','Poison','Commander Damage to You','Give Priority','Set Active Player','Knock Out Seat'],a=>{
     if(a==='Life')return numericControl('P'+id+' Life',st.life[id]??40,d=>apply('life',{d},id,{source:'solo-test'}));
     if(a==='Poison')return numericControl('P'+id+' Poison',st.poison[id]||0,d=>apply('counter',{k:'poison',d},id,{source:'solo-test'}));
     if(a==='Commander Damage to You'){let raw=prompt('Commander damage from P'+id+' to you','1'),n=Number(raw);if(Number.isFinite(n)&&n>0)apply('commanderDamage',{from:id,amount:n,damageType:'combat'},me,{source:'solo-test',sourceActorId:id});return}
     if(a==='Give Priority'){priorityOpen(id,'solo-test-manual',(st.stack||[]).at(-1)?.id||null,{source:'solo-test'});return}
     if(a==='Set Active Player'){st.active=id;if(st.priorityFlow?.windowId)priorityClose('solo-active-player-change',{source:'solo-test'});if(smartPriorityMode()==='full')priorityOpen(id,'solo-active-player-change',null,{source:'solo-test'});else{st.priority=null;st.respond=null;sync();send({t:'state',st})}return}
     if(a==='Knock Out Seat'){let delta=-(Number(st.life[id]??40));apply('life',{d:delta},id,{source:'solo-test'});return}
   })
 })
}
