 function connectedFrom(list){let seen=new Set(),out=[];for(const p of Array.isArray(list)?list:[]){let id=Number(p?.id);if(!Number.isInteger(id)||id<1||id>8||p?.connected===false||seen.has(id))continue;seen.add(id);out.push({id,name:String(p?.name||('Player '+id))})}return out.sort((a,b)=>a.id-b.id).slice(0,8)}
