 function snapshot(reason='read'){let live=connected(),n=Math.max(1,Math.min(8,live.length||1));return{version:VERSION,reason:String(reason||'read'),connectedCount:n,connectedPlayerIds:live.map(p=>p.id),localPlayerId:typeof me==='number'?Number(me):1,isHost:typeof HST!=='undefined'?!!HST:false,room:typeof activeRoom!=='undefined'&&activeRoom?String(activeRoom):null,lobbyMusicPerDevice:MTG_LOBBY_VOLUME_BY_CONNECTED[n],spatialBattlefieldAudio:'reserved-for-later'}}
 let lastSignature='';
 function publish(reason='refresh'){let snap=snapshot(reason),sig=snap.connectedCount+'|'+snap.connectedPlayerIds.join(',')+'|'+(snap.room||'');try{document.documentElement.dataset.mtgConnectedPlayers=String(snap.connectedCount);document.body?.setAttribute('data-mtg-connected-players',String(snap.connectedCount))}catch{}if(sig!==lastSignature){lastSignature=sig;try{window.dispatchEvent(new CustomEvent('mtgte:table-audio-context',{detail:snap}))}catch{}}return snap}
 function localQA(){let checks=[];for(let n=1;n<=8;n++){let list=Array.from({length:n},(_,i)=>({id:i+1,connected:true}));checks.push(['exact connected count '+n,countFrom(list)===n])}checks.push(['offline seats are excluded',countFrom([{id:1,connected:true},{id:2,connected:false},{id:3,connected:true}])===2]);checks.push(['duplicate seat ids do not double count',countFrom([{id:1,connected:true},{id:1,connected:true},{id:2,connected:true}])===2]);checks.push(['table count is capped at eight',countFrom(Array.from({length:12},(_,i)=>({id:i+1,connected:true})))===8]);return{version:VERSION,ok:checks.every(x=>x[1]),checks}}
