globalThis.MTGAudioTableContext=MTGAudioTableContext;
function lobbyMusicSeatCount(){return MTGAudioTableContext.count()}
function lobbyMusicPerDevice(){let n=lobbyMusicSeatCount();return MTG_LOBBY_VOLUME_BY_CONNECTED[n]??MTG_LOBBY_VOLUME_BY_CONNECTED[1]}
