function refreshAudioTableContext(reason='refresh'){let snap=MTGAudioTableContext.publish(reason);if(warScore.desiredMode==='lobby'&&warScore.audio&&!warScore.audio.paused){let next=scoreModeMaster('lobby');if(Math.abs(Number(warScore.targetVolume||0)-next)>.0001){warScore.targetVolume=next;fadeExactScore(next,.5)}}return snap}
