function ensureExactScoreElement(){let a=$('mtgteExactLobbyScore');if(!a){a=document.createElement('audio');a.id='mtgteExactLobbyScore';a.src=MTG_EXACT_SCORE_SRC;a.preload='auto';a.loop=true;a.setAttribute('playsinline','');a.setAttribute('webkit-playsinline','');a.setAttribute('aria-hidden','true');a.style.display='none';document.body.appendChild(a)}a.loop=true;warScore.audio=a;return a}
function fadeExactScore(target,seconds=.8,onDone=null){let a=ensureExactScoreElement(),to=Math.max(0,Math.min(1,Number(target)||0)),from=Math.max(0,Math.min(1,Number(a.volume)||0)),duration=Math.max(.05,Number(seconds)||.8)*1000,start=performance.now();if(warScore.fadeFrame)cancelAnimationFrame(warScore.fadeFrame);function step(now){let p=Math.min(1,(now-start)/duration),e=p*p*(3-2*p);a.volume=from+(to-from)*e;if(p<1)warScore.fadeFrame=requestAnimationFrame(step);else{warScore.fadeFrame=0;a.volume=to;if(onDone)onDone()}}warScore.fadeFrame=requestAnimationFrame(step)}
