function startRenderedSources(){return true}
function updateRenderedScoreMix(identity=null,mode=warScore.mode||warScore.desiredMode||'verify'){warScore.identity=Array.isArray(identity)?identity.slice():scoreIdentity();if(warScore.audio&&!warScore.audio.paused){warScore.targetVolume=scoreModeMaster(mode);fadeExactScore(warScore.targetVolume,.55)}return true}
async function startWarScore(mode='verify'){warScore.desiredMode=mode;warScore.mode=mode;warScore.fading=false;warScore.targetVolume=scoreModeMaster(mode);let a=ensureExactScoreElement();a.loop=true;a.muted=false;if(!a.paused){warScore.unlocked=true;fadeExactScore(warScore.targetVolume,mode==='lobby'?.72:.72);lobbyBed=warScore;return true}if(a.volume<=.0001)a.volume=.0001;try{await a.play();warScore.unlocked=true}catch{return false}fadeExactScore(warScore.targetVolume,mode==='lobby'?.9:1.15);lobbyBed=warScore;return true}
