function startLobbyAmbience(){warScore.desiredMode='lobby';refreshAudioTableContext('lobby-start');loadRenderedScoreAssets();return startWarScore('lobby')}
function fadeWarScore(seconds=.85){warScore.desiredMode=null;warScore.fading=true;clearTimeout(warScore.duckTimer);let a=ensureExactScoreElement();fadeExactScore(0,seconds,()=>{a.pause();try{a.currentTime=0}catch{}warScore.mode=null;warScore.fading=false;lobbyBed=null})}
function stopLobbyAmbience(){fadeWarScore(.65)}
