function cue(kind='soft'){if(!an)return;let ac=ensureAudio();if(!ac||ac.state!=='running')return;let o=ac.createOscillator(),g=ac.createGain(),now=ac.currentTime,f=kind==='ready'?196:kind==='battle'?98:132;o.type=kind==='battle'?'triangle':'sine';o.frequency.setValueAtTime(f,now);if(kind==='battle')o.frequency.exponentialRampToValueAtTime(294,now+.65);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(kind==='battle'?.043:.019,now+.025);g.gain.exponentialRampToValueAtTime(.0001,now+(kind==='battle'?.92:.38));o.connect(g).connect(ac.destination);o.start(now);o.stop(now+(kind==='battle'?.98:.42))}
