function activateSavedDeck(id,{close=true,silent=false}={}){let d=MTGProfileStore.activeDeck(playerProfile,id);if(!d)return false;persistActiveDeckSelection(id);hydrateProfileFromSavedDeck(d);renderDeckLibrary();try{slots()}catch{}if(close)closeDeckVault();else{vaultSelectedDeckId=id;renderDeckVault()}if(!silent)toast(d.name+' is now active.');return true}
function loadSavedDeck(id){return activateSavedDeck(id)}
function beginEditSavedDeck(id){let d=MTGProfileStore.activeDeck(playerProfile,id);if(!d)return;editingDeckId=id;editingPreviousActiveDeckId=activeDeckId;creatingNewDeckFromVault=false;$('deck').value=deckListText(d);prof={cards:[],mods:[],tags:[],capabilities:[],cardMap:new Map(),commander:d.commander||null,partner:d.partner||null};if($('formatSelect'))$('formatSelect').value=String(d.format||'commander').toLowerCase();$('vr').classList.add('h');$('commanderPick').classList.add('h');$('legalityReport').innerHTML='';$('tags').innerHTML='';$('conf').textContent='';$('verifyDetails').innerHTML='';$('saveDeckBtn').textContent='SAVE VERIFIED CHANGES';closeDeckVault();$('lobby').classList.add('h');$('setup').classList.remove('h');startVerifyAmbience();toast('Edit the list, then Verify Deck again before saving changes.')}
function beginNewDeckFromVault(){editingDeckId=null;editingPreviousActiveDeckId=activeDeckId;creatingNewDeckFromVault=true;$('deck').value='';prof={cards:[],mods:[],tags:[],capabilities:[],cardMap:new Map(),commander:null,partner:null};$('vr').classList.add('h');$('commanderPick').classList.add('h');$('legalityReport').innerHTML='';$('tags').innerHTML='';$('conf').textContent='';$('verifyDetails').innerHTML='';$('saveDeckBtn').textContent='SAVE TO DECK VAULT';closeDeckVault();$('lobby').classList.add('h');$('setup').classList.remove('h');startVerifyAmbience();toast('Import and verify the new deck. Your current active deck stays selected until you choose otherwise.')}
function renameSavedDeck(id,name){let d=MTGProfileStore.activeDeck(playerProfile,id),n=String(name||'').trim().replace(/\s+/g,' ').slice(0,32);if(!d||!n)return false;let result=MTGProfileStore.saveDeck(playerProfile,{...d,id:d.id,name:n});playerProfile=result.profile;saveProfile();vaultSelectedDeckId=id;vaultPanelMode='actions';renderDeckLibrary();renderDeckVault({preserveScroll:true});toast('Deck renamed.');return true}
function removeSavedDeck(id){let d=MTGProfileStore.activeDeck(playerProfile,id);if(!d)return;let wasActive=id===activeDeckId;playerProfile=MTGProfileStore.removeDeck(playerProfile,id);if(wasActive){persistActiveDeckSelection(null);prof={cards:[],mods:[],tags:[],capabilities:[],cardMap:new Map(),commander:null,partner:null};applyDeckTheme()}saveProfile();let decks=playerProfile.decks||[];vaultSelectedDeckId=decks[0]?.id||null;vaultPanelMode='actions';vaultDrawerOpen=false;vaultDrawerOpening=false;renderDeckLibrary();renderDeckVault({preserveScroll:true});toast(wasActive?'Deck removed. Choose another verified deck to make active.':'Deck removed from the Vault.')}
function handleDeckVaultCommand(cmd){let d=MTGProfileStore.activeDeck(playerProfile,vaultSelectedDeckId);if(!d&&cmd!=='new')return;if(cmd==='use')return activateSavedDeck(d.id);if(cmd==='edit'){vaultPanelMode='edit';return renderDeckVault({preserveScroll:true})}if(cmd==='rename'){vaultPanelMode='rename';renderDeckVault({preserveScroll:true});setTimeout(()=>$('vaultRenameInput')?.focus(),0);return}if(cmd==='save-rename')return renameSavedDeck(d.id,$('vaultRenameInput')?.value);if(cmd==='edit-list')return beginEditSavedDeck(d.id);if(cmd==='remove'){vaultPanelMode='remove';return renderDeckVault({preserveScroll:true})}if(cmd==='confirm-remove')return removeSavedDeck(d.id);if(cmd==='back-edit'){vaultPanelMode='edit';return renderDeckVault({preserveScroll:true})}if(cmd==='back'){vaultPanelMode='actions';return renderDeckVault({preserveScroll:true})}}
function saveCurrentDeck(){if(!playerProfile)return toast('Create a profile first.');if(!prof.cards?.length)return toast('Verify a deck first.');if(!prof.commander)return toast('Choose your commander first.');let editingExisting=editingDeckId?MTGProfileStore.activeDeck(playerProfile,editingDeckId):null,existing=editingExisting||(!creatingNewDeckFromVault?currentSavedDeck():null),name=editingExisting?.name||null;if(!name){name=prompt('Deck name',existing?.name||prof.commander||'My Deck');if(!name?.trim())return;name=name.trim()}let previousActive=editingPreviousActiveDeckId,result=MTGProfileStore.saveDeck(playerProfile,{id:existing?.id,name,commander:prof.commander,partner:prof.partner||null,format:$('formatSelect')?.value||'commander',colorIdentity:(typeof MTGDeckTheme!=='undefined'?MTGDeckTheme.identityFromProfile(prof):[]),list:prof.cards,rawText:$('deck').value,mechanics:prof.tags,quickActions:(prof.capabilities||[]).map(c=>c.action),privacy:existing?.privacy||'private'});playerProfile=result.profile;saveProfile();
 if(editingExisting){let saved=result.deck,editedWasActive=previousActive===saved.id;editingDeckId=null;editingPreviousActiveDeckId=null;$('saveDeckBtn').textContent='Save to Deck Library';if(editedWasActive||!previousActive){persistActiveDeckSelection(saved.id);hydrateProfileFromSavedDeck(saved)}else{persistActiveDeckSelection(previousActive);let prior=MTGProfileStore.activeDeck(playerProfile,previousActive);if(prior)hydrateProfileFromSavedDeck(prior)}$('setup').classList.add('h');$('lobby').classList.remove('h');startLobbyAmbience();renderDeckLibrary();setTimeout(()=>openDeckVault(saved.id),0);toast('Verified deck changes saved.');return}
 if(creatingNewDeckFromVault){let saved=result.deck;creatingNewDeckFromVault=false;editingPreviousActiveDeckId=null;$('saveDeckBtn').textContent='Save to Deck Library';if(previousActive&&MTGProfileStore.activeDeck(playerProfile,previousActive)){persistActiveDeckSelection(previousActive);hydrateProfileFromSavedDeck(MTGProfileStore.activeDeck(playerProfile,previousActive))}else{persistActiveDeckSelection(saved.id);hydrateProfileFromSavedDeck(saved)}$('setup').classList.add('h');$('lobby').classList.remove('h');startLobbyAmbience();renderDeckLibrary();setTimeout(()=>openDeckVault(saved.id),0);toast('Verified deck stored in the Vault.');return}
 persistActiveDeckSelection(result.deck.id);renderDeckLibrary();toast(result.created?'Deck saved.':'Deck version saved.')}
$('saveDeckBtn').onclick=saveCurrentDeck;if($('deckVaultLock'))$('deckVaultLock').onclick=()=>openDeckVault();
